// Function to calculate tax on money
function taxMoney(cents, ratePct) {
    // Calculate tax amount: net * ratePct / 100
    const tax = Math.round(cents * ratePct) / 100;

    // Gross is net plus tax
    const gross = cents + tax;

    // Return the result object
    return {
        net: cents,
        tax: tax,
        gross: gross
    };
}

// Export the function
module.exports = {
    parseMoney,
    formatMoney,
    addMoney,
    subtractMoney,
    multiplyMoney,
    splitMoney,
    allocateMoney,
    taxMoney
};

const { taxMoney } = require('./r8_money.js');

// Test the taxMoney function
console.log('Testing taxMoney function:');
console.log('taxMoney(100, 10):', taxMoney(100, 10));
console.log('taxMoney(500, 20):', taxMoney(500, 20));
console.log('taxMoney(1000, 15):', taxMoney(1000, 15));

